<div class="form-grid"><label class="field sm:col-span-2"><span>Common photo preset</span><select id="photo-preset"><option value="35,45">35 × 45 mm (common passport)</option><option value="51,51">51 × 51 mm (US 2 × 2 in)</option><option value="50,70">50 × 70 mm (Canada)</option><option value="custom">Custom dimensions</option></select></label><label class="field"><span>Photo width (mm)</span><input id="photo-width" type="number" name="photo_width_mm" min="20" max="100" step="0.1" value="35" required></label><label class="field"><span>Photo height (mm)</span><input id="photo-height" type="number" name="photo_height_mm" min="20" max="100" step="0.1" value="45" required></label><label class="field"><span>Paper</span><select name="paper"><option value="a4">A4</option><option value="4x6">4 × 6 inch</option></select></label><label class="field"><span>Background</span><input type="color" name="background_color" value="#ffffff"></label><label class="field"><span>Margin (mm)</span><input type="number" name="margin_mm" min="0" max="30" step="0.5" value="10"></label><label class="field"><span>Gap (mm)</span><input type="number" name="gap_mm" min="0" max="20" step="0.5" value="3"></label><label class="check sm:col-span-2"><input type="checkbox" name="remove_background" value="1"><span>Remove original background first <small>(requires local AI service)</small></span></label></div>
